import{_ as e,c as a,o as s,a2 as i}from"./chunks/framework.CAZbn8JG.js";const u=JSON.parse('{"title":"Sample Project Overview","description":"Metal:Middleware, ETL & AI at the same place. Empower your projects with a free open-source data transformation solution","frontmatter":{"description":"Metal:Middleware, ETL & AI at the same place. Empower your projects with a free open-source data transformation solution"},"headers":[],"relativePath":"sample-project.md","filePath":"sample-project.md","lastUpdated":1731760017000}'),r={name:"sample-project.md"};function o(l,t,d,n,h,p){return s(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="sample-project-overview" tabindex="-1">Sample Project Overview <a class="header-anchor" href="#sample-project-overview" aria-label="Permalink to &quot;Sample Project Overview&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This sample project showcases a Docker Compose stack comprising Metal Server and various Database Management System (DBMS) providers.</p><p>The stack comes preloaded with data, facilitating the execution and testing of diverse use cases.</p><p>The project has been tested on:</p><ul><li>CentOS 7</li><li>Ubuntu 22</li></ul><h3 id="stack-services" tabindex="-1">Stack Services <a class="header-anchor" href="#stack-services" aria-label="Permalink to &quot;Stack Services&quot;">​</a></h3><p>Here&#39;s an overview of the key services included in the stack:</p><table tabindex="0"><thead><tr><th>Service Name</th><th>Description</th><th>Docker Image</th></tr></thead><tbody><tr><td>metal</td><td>Metal Server</td><td><a href="https://github.com/anismegdiche/metal-sample-project/blob/master/sample/metal-server/dockerfile" target="_blank" rel="noreferrer">metal-server Dockerfile</a></td></tr><tr><td>mdb-mflix</td><td>MongoDB</td><td>mongo:latest</td></tr><tr><td>ms-hr</td><td>MS SQL Server 2019</td><td>mcr.microsoft.com/mssql/server:2019-latest</td></tr><tr><td>pg-northwind</td><td>PostgreSQL Server</td><td>postgres:latest</td></tr><tr><td>pg-clubdata</td><td>PostgreSQL Server</td><td>postgres:latest</td></tr><tr><td>pg-clubdata-bookings</td><td>PostgreSQL Server</td><td>postgres:latest</td></tr><tr><td>pg-clubdata-members</td><td>PostgreSQL Server</td><td>postgres:latest</td></tr><tr><td>pg-clubdata-facilities</td><td>PostgreSQL Server</td><td>postgres:latest</td></tr><tr><td>azurite</td><td>Microsoft Azure Storage Azurite</td><td>mcr.microsoft.com/azure-storage/azurite:latest</td></tr><tr><td>ftp-server</td><td>FTP Server</td><td>garethflowers/ftp-server:latest</td></tr></tbody></table><h3 id="databases" tabindex="-1">Databases <a class="header-anchor" href="#databases" aria-label="Permalink to &quot;Databases&quot;">​</a></h3><p>For each DBMS, the project includes specific databases with associated tables or collections:</p><table tabindex="0"><thead><tr><th>Service Name</th><th>Database Name</th><th>Tables/Collections Names</th></tr></thead><tbody><tr><td>mdb-mflix</td><td>mflix</td><td>movies, users, sessions, comments, theaters</td></tr><tr><td>ms-hr</td><td>hr</td><td>regions, countries, locations, jobs, departments, employees, dependents</td></tr><tr><td>pg-northwind</td><td>northwind</td><td>territories, order_details, employee_territories, us_states, customers, orders, employees, shippers, products, categories, suppliers, region, customer_demographics, customer_customer_demo</td></tr><tr><td>pg-clubdata</td><td>clubdata</td><td>members, facilities, bookings, mflix_log</td></tr><tr><td>pg-clubdata-members</td><td>clubdata</td><td>members</td></tr><tr><td>pg-clubdata-facilities</td><td>clubdata</td><td>facilities</td></tr><tr><td>pg-clubdata-bookings</td><td>clubdata</td><td>bookings</td></tr></tbody></table><h3 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h3><p>The project includes files to be used with File Data provider:</p><table tabindex="0"><thead><tr><th>File Name</th><th>Storage</th><th>Content</th></tr></thead><tbody><tr><td><a href="https://github.com/anismegdiche/metal-sample-project/blob/0.2/sample/azurite/datacontainer1/colors.json" target="_blank" rel="noreferrer">colors.json</a></td><td>azurite (datacontainer1)</td><td>JSON data</td></tr><tr><td><a href="https://github.com/anismegdiche/metal-sample-project/blob/0.2/sample/azurite/datacontainer1/addresses.csv" target="_blank" rel="noreferrer">addresses.csv</a></td><td>azurite (datacontainer1)</td><td>CSV data</td></tr></tbody></table><h3 id="configuration-file" tabindex="-1">Configuration File <a class="header-anchor" href="#configuration-file" aria-label="Permalink to &quot;Configuration File&quot;">​</a></h3><p>The project includes a readily available configuration file for seamless setup. <a href="https://github.com/anismegdiche/metal-server/blob/main/config/config-sample-docker.yml" target="_blank" rel="noreferrer">Configuration File</a></p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before delving into the sample project, ensure that your environment meets the following prerequisites:</p><ul><li><a href="https://www.docker.com/" target="_blank" rel="noreferrer">Docker</a> 27 or newer</li><li><a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a> 2.47 or newer</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Follow these steps to install the sample project:</p><ol><li><p>Clone the sample project repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/anismegdiche/metal-sample-project.git</span></span></code></pre></div></li><li><p>Navigate to the project folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> metal-sample-project</span></span></code></pre></div></li><li><p>Change the permissions of the <code>install.sh</code> script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.sh</span></span></code></pre></div></li><li><p>Run the installation script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>The stack will be up and ready after the installation process.</p></li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>To ensure everything is set up correctly, run the following command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/server/info</span></span></code></pre></div><p>You sould receive the following response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;server&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Metal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Congratulations! You have successfully configured and verified your Metal Server Sample Project.</p><p>For more configuration details and use cases, please refer to the section <a href="https://metal-docs-sh3b0.kinsta.page/guides/technical-guides.html" target="_blank" rel="noreferrer">Technical Guides</a></p>',30)])])}const m=e(r,[["render",o]]);export{u as __pageData,m as default};
